def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)

    if not alive_opps:
        return float(min(budget, 25.0))

    prev_bids = []
    strong_prev_bids = []
    weak_count = 0
    urgent_opp_count = 0

    for opp in alive_opps:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
            urgent_opp_count += 1
        if opp.get('hp', 0) <= 3 or opp.get('budget', 0) < 80:
            weak_count += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if isinstance(prev, dict) else None
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('budget', 0) >= 100 and opp.get('hp', 0) > 3:
                strong_prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    strong_highest_prev = max(strong_prev_bids) if strong_prev_bids else highest_prev

    tight_supply = supply <= 17
    loose_supply = supply >= 22
    my_urgent = hp <= 3 or no_water_days >= 2
    my_risky = hp <= 5 or no_water_days >= 1

    if my_urgent:
        target = max(110.0, strong_highest_prev + 2.0)
        if tight_supply:
            target = max(target, 145.0)
        elif loose_supply:
            target = max(target, 118.0)
    elif my_risky:
        if tight_supply:
            target = max(95.0, strong_highest_prev + 1.5)
        elif loose_supply:
            target = max(62.0, strong_highest_prev * 0.72)
        else:
            target = max(78.0, strong_highest_prev * 0.82)
    else:
        if tight_supply:
            target = max(88.0, strong_highest_prev * 0.78)
        elif loose_supply:
            target = max(38.0, strong_highest_prev * 0.42)
        else:
            target = max(58.0, strong_highest_prev * 0.58)

    if weak_count >= 2 and not my_urgent:
        target *= 0.9
    if urgent_opp_count >= 2 and tight_supply:
        target *= 1.08

    days_left = max(0, 10 - int(day))
    reserve = days_left * 18.0
    affordable = max(0.0, budget - reserve)

    if my_urgent:
        cap = budget
    else:
        cap = max(35.0, affordable + 20.0)
        cap = min(cap, budget)

    bid = min(target, cap)

    if budget < 60:
        bid = min(bid, budget)
    if not my_urgent and loose_supply and hp >= 7 and no_water_days == 0:
        bid = min(bid, 55.0)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = float(budget)

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(float(my_status.get('budget', 0.0)), DAILY_SALARY * 0.4))

    # Immediate reaction from yesterday's trace bids
    prev_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Supply pressure: near upper range, expect stronger competition.
    # Use a smooth threshold rather than exact equilibrium.
    supply_frac = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_frac = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    if supply_frac < 0.0:
        supply_frac = 0.0
    if supply_frac > 1.0:
        supply_frac = 1.0

    # If opponents previously bid very high, match a fraction to steal water.
    # Otherwise, bid enough to be competitive.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Competitors are likely in survival mode.
        if hp <= 2.0 or no_water_days >= 2:
            target = DAILY_SALARY * (0.85 + 0.1 * supply_frac)
        else:
            target = DAILY_SALARY * (0.55 + 0.25 * supply_frac)
    else:
        # Moderate competition.
        if hp <= 2.0 or no_water_days >= 2:
            target = DAILY_SALARY * (0.75 + 0.15 * supply_frac)
        else:
            # Slightly above baseline to beat overcautious bidders.
            target = DAILY_SALARY * (0.45 + 0.20 * supply_frac)

    # Ensure we don't exceed budget; also keep a small reserve late in episode.
    episode_days = int(day_context.get('episode_days', 10)) if 'episode_days' in day_context else 10
    # day_context only has supply/day, so we infer remaining pressure from day.
    # If day is near end, preserve less.
    try:
        remaining = max(0, int(10) - int(day))
    except Exception:
        remaining = 5

    reserve_factor = 0.25 if remaining <= 2 else 0.35 if remaining <= 4 else 0.45
    max_affordable = budget
    min_reserve = budget * reserve_factor

    bid = min(max_affordable, target)
    if bid < 0.0:
        bid = 0.0

    # If we can afford it while keeping reserve, bid a bit higher when supply is high.
    if budget - bid > min_reserve and supply_frac > 0.6:
        bid = min(budget, bid + DAILY_SALARY * 0.08)

    # If hp is critically low, override reserve.
    if hp <= 1.5:
        bid = min(budget, DAILY_SALARY * 0.95)

    # Final clamp
    if bid > budget:
        bid = budget
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    strong_competitors = ["David", "Eric"]

    yesterday_bids = []
    for opp in alive_opponents:
        if opp['agent_id'] in strong_competitors:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                yesterday_bids.append(prev['bid'])

    current_supply = day_context['supply']
    current_day = day_context['day']

    base_bid = DAILY_SALARY * 0.85

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.9:
            base_bid = max(base_bid, highest_prev_bid + 3.0)
        else:
            base_bid = max(base_bid, highest_prev_bid + 1.0)

    if my_status['hp'] <= 3:
        base_bid = max(base_bid, DAILY_SALARY * 1.1)
    elif my_status['hp'] <= 5:
        base_bid = max(base_bid, DAILY_SALARY * 1.0)

    if current_supply < WATER_REQ * 1.5:
        base_bid *= 1.05
    elif current_supply >= WATER_REQ * 2:
        base_bid *= 0.95

    if current_day > EPISODE_DAYS / 2:
        base_bid *= 1.03

    final_bid = min(my_status['budget'], max(0.0, base_bid))

    if my_status['budget'] < DAILY_SALARY * 0.5 and my_status['hp'] <= 3:
        final_bid = my_status['budget']

    if final_bid < 1.0 and my_status['budget'] > 0:
        final_bid = min(my_status['budget'], 1.0)

    return float(final_bid)

